"""Write checker round-4 cross-family probe sources (ck4) into DEST. Usage: python3 -I gen_probes.py DEST"""
import json, sys
from pathlib import Path
dest = Path(sys.argv[1]); dest.mkdir(parents=True, exist_ok=False)
S = "@startuml\n{}\n@enduml\n"
C = []  # (name, body, intended_valid, axes, crlf)
def add(name, text, valid=True, axes=(), crlf=False, start="uml"):
    C.append((name, f"@start{start}\n{text}\n@end{start}\n", valid, list(axes), crlf))
# sequence
add("ck4_seq_apostrophe_word_trailing", "A -> B : don't /' c '/", axes=["sequence", "trailing", "apostrophe"])
add("ck4_seq_url_trailing", "A -> B : [[http://example.com/a]] go /' c '/", axes=["sequence", "trailing", "url"])
add("ck4_seq_creole_trailing", "A -> B : <b>bold</b> and <i>it</i> /' c '/", axes=["sequence", "trailing", "creole"])
add("ck4_seq_quoted_then_trailing", 'participant "Long Name" as L /\' c \'/\nL -> L : self', axes=["sequence", "trailing", "quotes"])
add("ck4_seq_span_in_quotes_trailing", 'participant "a /\' q" as Q \'/\nQ -> Q : x', axes=["sequence", "trailing", "quotes-unbalanced"])
add("ck4_seq_triple_in_quotes", 'A -> B : "x/\'\'\'k-1\'\'\'/y"', axes=["sequence", "special", "quotes"])
add("ck4_seq_triple_name", "Al/'''n'''/ice -> Bob : hi", axes=["sequence", "special", "identifier"])
add("ck4_seq_double_trailing_top", "A -> B : m /' a '/ /' b '/", axes=["sequence", "trailing-twice", "top-level-single-pass"])
add("ck4_seq_double_leading_top", "/' a '/ /' b '/ A -> B : m", axes=["sequence", "leading-twice", "top-level-single-pass"])
add("ck4_seq_note_multiline_body", "A -> B : x\nnote right\n/' c '/ body text\nmore /' d '/\nend note", axes=["sequence", "note", "leading", "trailing"])
add("ck4_seq_note_inline_trailing", "A -> B : x\nnote over A : hello /' c '/", axes=["sequence", "note", "trailing"])
add("ck4_seq_continuation_next_leading", "A -> B : one \\\n/' c '/ two", axes=["sequence", "continuation", "leading"])
add("ck4_seq_continuation_comment_only_then_msg", "/' c '/ \\\nA -> B : hi", axes=["sequence", "continuation", "comment-then-backslash"])
add("ck4_seq_crlf_trailing", "A -> B : hi /' c '/\n/' d '/ B -> A : back", axes=["sequence", "crlf", "trailing", "leading"], crlf=True)
add("ck4_seq_quote_slash_no_comment", 'A -> B : "a \'/ b" and it\'/s', axes=["sequence", "no-comment", "quote-slash"])
add("ck4_seq_trailing_slash_quote_only", "A -> B : x '/", axes=["sequence", "no-open", "trailing-close-only"])
add("ck4_seq_leading_space_trailing_spaces", "   /' c '/    A -> B : hi   ", axes=["sequence", "leading", "whitespace"])
add("ck4_seq_divider_trailing", "A -> B : x\n== Part /' c '/ ==\nB -> A : y", axes=["sequence", "middle-not-removed"])
add("ck4_seq_divider_end_trailing", "A -> B : x\n== Part == /' c '/\nB -> A : y", axes=["sequence", "trailing"])
add("ck4_seq_title_leading", "/' c '/ title My Title\nA -> B : x", axes=["sequence", "leading", "title"])
add("ck4_seq_skinparam_block", "skinparam sequence {\nArrowColor red /' c '/\n/' d '/ LifeLineBorderColor blue\n}\nA -> B : x", axes=["sequence", "skinparam-block"])
# class / object / component / usecase / state / activity
add("ck4_class_body_member_leading", "class A {\n/' c '/ +name : String\n+id : int /' d '/\n}", axes=["class", "body", "leading", "trailing"])
add("ck4_class_comment_then_backslash", "/' c '/ \\\nclass A", axes=["class", "continuation", "comment-then-backslash"])
add("ck4_class_note_multiline", "class A\nnote right of A\n/' c '/ first\nsecond /' d '/\nend note", axes=["class", "note"])
add("ck4_class_relation_label", "class A\nclass B\nA --> B : uses /' c '/", axes=["class", "relation", "trailing"])
add("ck4_class_special_in_name", "class Fo/'''x'''/o", axes=["class", "special"])
add("ck4_usecase_leading_actor_line", "/' c '/ actor Clerk\nClerk --> (Pay)", axes=["usecase", "leading"])
add("ck4_component_bracket_trailing", "[Engine] /' c '/\n[Engine] --> [Pump]", axes=["component", "trailing"])
add("ck4_state_body_leading", "state S {\n/' c '/ [*] --> T\n}", axes=["state", "body", "leading"])
add("ck4_activity3_if_trailing", "start\nif (ok?) then (yes) /' c '/\n:a;\nelse (no)\n:b;\nendif\nstop", axes=["activity3", "trailing"])
add("ck4_activity_legacy_trailing", "(*) --> \"First\" /' c '/\n\"First\" --> (*)", axes=["activity-legacy", "trailing"])
add("ck4_object_field_trailing", "object O {\nname = \"x\" /' c '/\n}", axes=["object", "trailing"])
# other families
add("ck4_yaml_trailing", "a: x /' c '/\nb: y", axes=["yaml", "trailing"], start="yaml")
add("ck4_json_leading_member", '{\n/\' c \'/ "a": 1,\n"b": 2\n}', axes=["json", "leading"], start="json")
add("ck4_mindmap_leading", "* root\n/' c '/ ** child\n** other", axes=["mindmap", "leading"], start="mindmap")
add("ck4_wbs_trailing", "* root\n** child /' c '/\n** other", axes=["wbs", "trailing"], start="wbs")
add("ck4_timing_trailing", "robust \"Web\" as W /' c '/\n@0\nW is Idle\n@10\nW is Busy", axes=["timing", "trailing"])
add("ck4_nwdiag_trailing", "nwdiag {\nnetwork dmz { /' c '/\naddress = \"210.x.x.x/24\"\nweb01 [address = \"210.x.x.1\"]; /' d '/\n}\n}", axes=["nwdiag", "trailing"])
add("ck4_ebnf_trailing", "a = \"x\" , b ; /' c '/\nb = \"y\" ;", axes=["ebnf", "trailing"], start="ebnf")
add("ck4_gantt_leading", "/' c '/ [Task] requires 3 days\n[Other] requires 2 days", axes=["gantt", "leading"], start="gantt")
add("ck4_salt_trailing", "salt\n{\nLogin | \"user\" /' c '/\n[OK] | [Cancel]\n}", axes=["salt", "trailing"])
# TIM
add("ck4_tim_procedure_double_trailing", "!procedure $p()\nA -> B : m /' a '/ /' b '/\n!endprocedure\n$p()", axes=["tim", "procedure", "double-pass"])
add("ck4_tim_procedure_double_leading", "!procedure $p()\n/' a '/ /' b '/ A -> B : m\n!endprocedure\n$p()", axes=["tim", "procedure", "double-pass"])
add("ck4_tim_function_return_trailing", "!function $f()\n!return \"val\" /' c '/\n!endfunction\nA -> B : $f()", axes=["tim", "function", "trailing"])
add("ck4_tim_define_value_trailing", "!define GREET hello /' c '/\nA -> B : GREET world", axes=["tim", "define", "trailing"])
add("ck4_tim_definelong_body", "!definelong DL()\nA -> B : dl /' c '/\n!enddefinelong\nDL()", axes=["tim", "definelong", "trailing"])
add("ck4_tim_while_body", "!$i = 0\n!while $i < 2 /' c '/\nA -> B : m$i /' d '/\n!$i = $i + 1\n!endwhile", axes=["tim", "while", "trailing"])
add("ck4_tim_foreach_body", "!foreach $x in [\"p\", \"q\"]\n/' c '/ A -> B : $x\n!endfor", axes=["tim", "foreach", "leading"])
add("ck4_tim_include_trailing", "!include ck4inc.iuml /' c '/\nA -> B : main", axes=["tim", "include", "trailing"])
add("ck4_tim_include_body_comments", "!include ck4inc2.iuml\nA -> B : main", axes=["tim", "include-body", "leading", "trailing"])
add("ck4_tim_var_string_comment", "!$v = \"a /' b '/ c\"\nA -> B : $v", axes=["tim", "string-middle"])
add("ck4_tim_if_else_comment", "!$x = 1\n!if $x == 2\nA -> B : no\n!else /' c '/\nA -> B : yes\n!endif", axes=["tim", "if", "trailing"])
add("ck4_tim_startsub_inplace_double", "!startsub S\nA -> B : s /' a '/ /' b '/\n!endsub", axes=["tim", "startsub-in-place", "single-pass"])
add("ck4_tim_includesub_double", "!includesub ck4sub.iuml!S\nA -> B : main", axes=["tim", "includesub", "double-pass"])
add("ck4_activity3_comment_then_backslash", "start\n/' c '/ \\\n:act;\nstop", axes=["activity3", "continuation", "comment-then-backslash"])
add("ck4_component_comment_then_backslash", "/' c '/ \\\n[Engine] --> [Pump]", axes=["component", "continuation", "comment-then-backslash"])
add("ck4_state_comment_then_backslash", "/' c '/ \\\n[*] --> S1", axes=["state", "continuation", "comment-then-backslash"])
add("ck4_class_continuation_next_leading", "class A\nclass B\nA --> B : one \\\n/' c '/ two", axes=["class", "continuation", "leading"])
# source-line attribution controls for mk4_tim_sprite_in_procedure
add("ck4_ctl_procedure_four_classes", "!procedure $mk()\nclass P1\nclass P2\nclass P3\nclass P4\n!endprocedure\n$mk()\nclass Oak", axes=["control", "procedure", "source-line"])
add("ck4_ctl_procedure_sprite_nocomment", "!procedure $mk()\nsprite $dot [2x2/16] {\nF0\n0F\n}\n!endprocedure\n$mk()\nclass Oak\nclass Elm", axes=["control", "procedure", "sprite", "source-line"])
add("ck4_procedure_sprite_end_comment_two", "!procedure $mk()\nsprite $dot [2x2/16] {\nF0\n0F\n} /' e '/\n!endprocedure\n$mk()\nclass Elm\nclass Oak", axes=["procedure", "sprite", "source-line", "trailing"])
# intended invalid
add("ck4_inv_nbsp_leading_comment_seq", " /' c '/ A -> B : x", valid=False, axes=["sequence", "nbsp", "java-trim"])
add("ck4_inv_include_missing_after_comment", "/' c '/ !include ck4-missing.iuml\nA -> B", valid=False, axes=["tim", "include", "leading"])
add("ck4_inv_class_after_leading_two", "/' a '/ /' b '/ class A", valid=False, axes=["class", "leading-twice"])
for name, text, valid, axes, crlf in C:
    data = text.replace("\n", "\r\n") if crlf else text
    (dest / f"{name}.puml").write_bytes(data.encode())
(dest / "ck4inc.iuml").write_bytes(b"A -> B : included\n")
(dest / "ck4sub.iuml").write_bytes("@startuml\n!startsub S\nA -> B : s /' a '/ /' b '/\n!endsub\n@enduml\n".encode())
(dest / "ck4inc2.iuml").write_bytes("/' c '/ A -> B : inc1\nB -> A : inc2 /' d '/\n".encode())
(dest / "cases.json").write_text(json.dumps([dict(name=n, intended_valid=v, axes=a, crlf=c) for n, _, v, a, c in C], indent=1))
print(len(C))
